// intent: Verify to_bson writing via adapter/output sink handles the updated single-pass method correctly.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

struct custom_sink {
    std::vector<char> buffer;
    void write_character(char c) { buffer.push_back(c); }
    void write_characters(const char* s, std::size_t length) {
        buffer.insert(buffer.end(), s, s + length);
    }
    std::size_t written() const { return buffer.size(); }
};

int main() {
    try {
        nlohmann::json j = {{"key", "value"}};
        custom_sink s;
        nlohmann::json::to_bson(j, s);
        std::cout << "sink_size: " << s.buffer.size() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
}
